"""Prepared r10 cold/warm central MCP acceptance; default is read-only.

No stop/cancel/deprovision/replay, authority renewal or service operation.
Fresh runtime and authority pins must come from reviewed rollout receipts.
Timeout mode is excluded: the approved test does not deterministically exceed5s.
"""

import argparse
import base64
import hashlib
import json
import os
from pathlib import Path
import re
import sqlite3
import stat
import time
import urllib.request

# Embedded reviewed guard; only definitions load because its main is disabled.
# The generator binds this exact public helper source to its retained digest.
GUARD_SHA256 = "ab182f47b605e5edac1e30cb9cdf48ca53a571f0cbb5367a0f6fb837cbe0c9af"
GUARD_SOURCE_BASE64 = ""
_guard = {"__name__": "r10_authority_guard"}
_guard_source = base64.b64decode(GUARD_SOURCE_BASE64)
if hashlib.sha256(_guard_source).hexdigest() != GUARD_SHA256:
    raise SystemExit("GUARD_SOURCE_HASH_MISMATCH")
exec(compile(_guard_source, "reviewed-r10-authority-guard", "exec"), _guard)
require = _guard["require"]
emit = _guard["emit"]
digest = _guard["digest"]

# Fresh values are populated only from the reviewed public pin document in main.
INSTANCE = EPOCH = NATIVE_PROCESS = NATIVE_SERVER = CONTEXT = PILOT = None
EXPIRY = 0
PINS = {}
ARGV = ["node", "--test", "tests/control-plane-approved-patch-runtime.test.js"]
TERMINAL = {"completed", "failed", "rejected", "stopped"}
ORIGINAL_ACTIONS = {"act_4193cf69c84542e7b13a91e492916ccd", "act_fc024ff0b54c4a8ba4c7c7b0228a7e76"}


def rows(database: Path, sql: str, parameters=()) -> list[dict]:
    with sqlite3.connect(database.as_uri() + "?mode=ro", uri=True, timeout=5) as db:
        db.row_factory = sqlite3.Row
        db.execute("PRAGMA query_only=ON")
        db.execute("BEGIN")
        return [dict(row) for row in db.execute(sql, parameters)]


def mcp_credentials() -> tuple[str, str]:
    path = Path("/home/svhome/.config/codex-control-plane/mcp-tunnel.env")
    raw = _guard["protected_file"](path).decode()
    import shlex
    values = {}
    for line in raw.splitlines():
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        key, value = line.split("=", 1)
        require(key not in values, "TUNNEL_CONFIG_DUPLICATE_KEY")
        parts = shlex.split(value, comments=True)
        require(len(parts) <= 1, "TUNNEL_CONFIG_VALUE_INVALID")
        values[key.strip()] = parts[0] if parts else ""
    header = Path(values["CONTROL_PLANE_MCP_AUTH_HEADER_FILE"])
    require(header.is_absolute() and header.is_file() and not header.is_symlink()
            and header.resolve().is_relative_to(Path("/home/svhome")), "HEADER_PATH_UNSAFE")
    metadata = header.stat()
    require(metadata.st_uid == os.getuid() and stat.S_IMODE(metadata.st_mode) in (0o400, 0o600), "HEADER_FILE_ACL_INVALID")
    authorization = header.read_text().strip()
    require(authorization.startswith("Bearer ") and "\n" not in authorization and "\r" not in authorization, "HEADER_FORMAT_INVALID")
    config = _guard["environment"]()
    port = config.get("CONTROL_PLANE_MCP_PORT", "8766")
    require(port.isdigit() and 1 <= int(port) <= 65535, "MCP_PORT_INVALID")
    return "http://127.0.0.1:" + port, authorization


def call(origin: str, authorization: str, name: str, arguments: dict) -> dict:
    request = urllib.request.Request(origin + "/mcp", data=json.dumps({
        "jsonrpc": "2.0", "id": str(time.time_ns()), "method": "tools/call",
        "params": {"name": name, "arguments": arguments},
    }).encode(), headers={"Authorization": authorization, "Content-Type": "application/json"}, method="POST")
    try:
        with urllib.request.urlopen(request, timeout=20) as response:
            result = json.load(response)
    except Exception:
        raise _guard["GuardFailure"]("MCP_TRANSPORT_UNCERTAIN_NO_RETRY") from None
    require(isinstance(result, dict) and "error" not in result, "MCP_PROTOCOL_ERROR")
    value = result.get("result", {})
    require(isinstance(value, dict) and value.get("isError") is not True, "MCP_TOOL_REJECTED")
    structured = value.get("structuredContent")
    require(isinstance(structured, dict), "MCP_TOOL_RESPONSE_INVALID")
    return structured


def authority_guard(overview: dict, grant: dict, *, require_window: bool = True) -> None:
    now = int(time.time() * 1000)
    require(now + (600_000 if require_window else 0) < EXPIRY, "INSUFFICIENT_EXISTING_AUTHORITY_WINDOW")
    require(overview["admission"]["admission_mode"] == "scoped_pilot", "INTAKE_CHANGED")
    require(grant["expires_at_ms"] >= EXPIRY, "SERVICE_GRANT_WINDOW_CHANGED")
    contexts = [item for item in overview["contexts"] if item.get("context_id") == CONTEXT]
    pilots = [item for item in overview["scoped_pilot_decisions"] if item.get("decision_id") == PILOT]
    require(len(contexts) == len(pilots) == 1 and contexts[0]["closed_at_ms"] is None
            and contexts[0]["binding_id"] == _guard["BINDING"] and contexts[0]["expires_at_ms"] == EXPIRY,
            "APPROVED_STANDING_CONTEXT_CHANGED")
    require(pilots[0]["revoked_at_ms"] is None and pilots[0]["expires_at_ms"] == EXPIRY
            and pilots[0]["binding_id"] == _guard["BINDING"] and pilots[0]["principal_id"] == _guard["PRINCIPAL"],
            "APPROVED_PILOT_CHANGED")
    nodes = [item for item in overview["nodes"] if item.get("device_id") == _guard["DEVICE"]]
    require(len(nodes) == 1 and nodes[0]["activation_epoch"] == EPOCH
            and nodes[0]["readiness"] == "ready" and nodes[0]["policy_state"] == "enabled"
            and isinstance(nodes[0]["last_seen_at_ms"], int) and not isinstance(nodes[0]["last_seen_at_ms"], bool)
            and 0 <= now - nodes[0]["last_seen_at_ms"] < 60_000
            and isinstance(nodes[0]["policy_expires_at_ms"], int) and not isinstance(nodes[0]["policy_expires_at_ms"], bool)
            and nodes[0]["policy_expires_at_ms"] > now
            and nodes[0]["runtime_instance_id"] == NATIVE_PROCESS
            and nodes[0]["mcp_server_instance_id"] == NATIVE_SERVER,
            "R10_FRESH_READY_NODE_UNPROVEN")


def terminal_family(database: Path, action_id: str, task_id: str) -> dict:
    require(re.fullmatch(r"act_[a-f0-9]{32}", action_id) and action_id not in ORIGINAL_ACTIONS, "NEW_ACTION_REQUIRED")
    action = rows(database, "SELECT * FROM actions WHERE action_id=?", (action_id,))
    intent = rows(database, "SELECT * FROM mcp_exec_intents WHERE action_id=?", (action_id,))
    links = rows(database, "SELECT * FROM mcp_task_action_links WHERE task_id=?", (task_id,))
    require(len(action) == len(intent) == len(links) == 1 and links[0]["action_id"] == action_id
            and intent[0]["task_id"] == task_id and intent[0]["binding_id"] == _guard["BINDING"]
            and intent[0]["principal_id"] == _guard["PRINCIPAL"], "EXACT_CANARY_FAMILY_REQUIRED")
    require(action[0]["binding_id"] == _guard["BINDING"] and action[0]["device_id"] == _guard["DEVICE"]
            and action[0]["workspace_id"] == _guard["WORKSPACE"]
            and action[0]["workspace_generation"] == _guard["GENERATION"]
            and action[0]["owner_id"] == intent[0]["owner_id"] and action[0]["request_id"] == intent[0]["request_id"]
            and action[0]["created_at_ms"] == intent[0]["created_at_ms"]
            and action[0]["scoped_pilot_decision_id"] == PILOT, "EXACT_CANARY_TARGET_CHANGED")
    require(json.loads(intent[0]["argv_json"]) == {"argv": ARGV} and intent[0]["timeout_ms"] == 300000
            and intent[0]["max_output_bytes"] == 32768 and intent[0]["cwd"] == "", "EXACT_CANARY_ARGUMENTS_CHANGED")
    require(action[0]["delivery_state"] == "settled" and action[0]["settled_at_ms"] is not None, "ACTION_NOT_SETTLED")
    receipts = rows(database, "SELECT * FROM receipts WHERE action_id=? ORDER BY received_at_ms,receipt_id", (action_id,))
    require(receipts and receipts[-1]["receipt_state"] in TERMINAL, "TERMINAL_RECEIPT_REQUIRED")
    require(receipts[-1]["device_id"] == _guard["DEVICE"], "EXACT_RECEIPT_DEVICE_REQUIRED")
    attempts = rows(database, "SELECT * FROM delivery_attempts WHERE action_id=?", (action_id,))
    require(len(attempts) == 1, "SINGLE_ATTEMPT_REQUIRED")
    payload = json.loads(receipts[-1]["payload_json"])
    runtime = payload.get("runtime_identity", {})
    require(runtime.get("activation_epoch_id") == EPOCH and runtime.get("process_instance_id") == NATIVE_PROCESS
            and runtime.get("server_instance_id") == NATIVE_SERVER
            and runtime.get("tool_contract_sha256") == PINS["native_contract_sha256"], "EXACT_R10_NATIVE_RECEIPT_REQUIRED")
    require(payload.get("task_id") == task_id and payload.get("action_id") == action_id, "RECEIPT_FAMILY_CHANGED")
    return {"action": action[0], "intent": intent[0], "receipt": receipts[-1], "payload": payload, "attempt": attempts[0]}


def cleanup_family(origin: str, token: str, mcp_origin: str, authorization: str, database: Path,
                   action_id: str, task_id: str) -> None:
    family = terminal_family(database, action_id, task_id)
    preserve = digest(family)
    call(mcp_origin, authorization, "task_control", {"operation": "writer_release", "task_id": task_id, "reason": "r10_mcp_canary_terminal"})
    call(mcp_origin, authorization, "workspace_context", {"operation": "task_close", "task_id": task_id})
    tasks = rows(database, "SELECT * FROM mcp_task_sessions WHERE task_id=?", (task_id,))
    writers = rows(database, "SELECT * FROM mcp_task_writer_leases WHERE task_id=?", (task_id,))
    require(len(tasks) == 1 and tasks[0]["closed_at_ms"] is not None and all(row["released_at_ms"] is not None for row in writers), "TASK_WRITER_CLEANUP_UNPROVEN")
    require(digest(terminal_family(database, action_id, task_id)) == preserve, "CANARY_HISTORY_CHANGED")
    context_id = family["action"]["context_id"]
    require(context_id != CONTEXT and re.fullmatch(r"ctx_[a-f0-9]{32}", context_id), "TEMPORARY_CONTEXT_REQUIRED")
    contexts = rows(database, "SELECT * FROM contexts WHERE context_id=?", (context_id,))
    requests = rows(database, "SELECT * FROM work_requests WHERE request_id=?", (family["action"]["request_id"],))
    require(len(contexts) == len(requests) == 1 and contexts[0]["owner_id"] == tasks[0]["owner_id"]
            and contexts[0]["binding_id"] == _guard["BINDING"] and contexts[0]["created_at_ms"] == family["action"]["created_at_ms"]
            and contexts[0]["expires_at_ms"] == family["action"]["expires_at_ms"] and requests[0]["context_id"] == context_id,
            "TEMPORARY_CONTEXT_AUTHORITY_CHANGED")
    require(rows(database, "SELECT action_id FROM actions WHERE context_id=?", (context_id,)) == [{"action_id": action_id}]
            and not rows(database, "SELECT grant_id FROM mcp_access_grants WHERE context_id=?", (context_id,)), "TEMPORARY_CONTEXT_SHARED")
    closed = _guard["api"](origin, token, "/v1/contexts/" + context_id + "/close", {})
    require(closed.get("context_id") == context_id and closed.get("closed_at_ms") is not None, "CONTEXT_CLOSE_ACK_UNPROVEN")
    require(digest(terminal_family(database, action_id, task_id)) == preserve, "CLEANUP_MUTATED_CANARY_EVIDENCE")
    overview = _guard["api"](origin, token, "/v1/ui/overview")
    authority_guard(overview, _guard["target"](overview), require_window=False)
    emit("r10_mcp_canary_cleanup_complete", action_id=action_id, task_id=task_id, context_id=context_id,
         standing_context_preserved=CONTEXT, command_replayed=False, writer_released=True, task_closed=True)


def mode_keys(mode: str) -> tuple[str, str]:
    suffix = digest({"epoch": EPOCH, "context": CONTEXT, "pilot": PILOT, "mode": mode})
    return "r10-mcp-task-" + mode + "-" + suffix, "r10-mcp-exec-" + mode + "-" + suffix


def check_pins(pins: dict) -> None:
    patterns = {"service_instance_id": r"cp_[a-f0-9]{32}", "context_id": r"ctx_[a-f0-9]{32}",
                "pilot_id": r"pilot_[a-f0-9]{32}", "activation_epoch_id": r"activation-[A-Za-z0-9_-]{8,128}",
                "process_instance_id": r"[A-Za-z0-9_-]{8,128}", "server_instance_id": r"[A-Za-z0-9_-]{8,128}",
                "native_contract_sha256": r"[a-f0-9]{64}", "rollout_receipt_sha256": r"[a-f0-9]{64}",
                "native_observation_sha256": r"[a-f0-9]{64}"}
    require(set(pins) == set(patterns) | {"requested_at_ms", "expires_at_ms", "facade_contract"}, "EXACT_PUBLIC_PINS_REQUIRED")
    require(all(isinstance(pins[key], str) and re.fullmatch(pattern, pins[key]) for key, pattern in patterns.items()), "PIN_FORMAT_INVALID")
    require(pins["activation_epoch_id"] != "activation-mv3qe36p-991f11f44f47d32ea2e217b1db882ff7", "FRESH_R10_EPOCH_REQUIRED")
    require(isinstance(pins["requested_at_ms"], int) and not isinstance(pins["requested_at_ms"], bool)
            and isinstance(pins["expires_at_ms"], int) and not isinstance(pins["expires_at_ms"], bool)
            and pins["expires_at_ms"] - pins["requested_at_ms"] == 3600000, "EXACT_60M_WINDOW_REQUIRED")
    contract = pins["facade_contract"]
    require(isinstance(contract, dict) and set(contract) == {"schema_version", "profile", "sha256"}
            and isinstance(contract["schema_version"], int) and not isinstance(contract["schema_version"], bool)
            and isinstance(contract["profile"], str) and re.fullmatch(r"[A-Za-z0-9_-]{3,96}", contract["profile"])
            and isinstance(contract["sha256"], str) and re.fullmatch(r"[a-f0-9]{64}", contract["sha256"]), "EXACT_FACADE_CONTRACT_REQUIRED")


def tap_proof(output: str) -> dict:
    counts = {}
    for field, wanted in {"tests": 4, "pass": 4, "fail": 0, "cancelled": 0, "skipped": 0, "todo": 0}.items():
        matches = re.findall(r"^# " + field + r" (\d+)\s*$", output, re.MULTILINE)
        require(len(matches) == 1 and int(matches[0]) == wanted, "EXACT_FOUR_TEST_TAP_REQUIRED")
        counts[field] = wanted
    safe_lines = [line for line in output.splitlines() if re.fullmatch(r"TAP version 13|1\.\.4|# (tests|suites|pass|fail|cancelled|skipped|todo) [0-9]+", line)]
    return {"tap": counts, "tap_summary_lines": safe_lines[:9]}


def success(family: dict) -> None:
    payload = family["payload"]
    require(family["receipt"]["receipt_state"] == "completed" and payload.get("status") == "exited"
            and payload.get("timed_out") is False and payload.get("exit_code") == 0, "EXACT_SUCCESS_RECEIPT_REQUIRED")
    require(all(isinstance(payload.get(key), str) and re.fullmatch(r"[A-Za-z0-9_-]{1,128}", payload[key])
                for key in ("command_id", "job_id")), "NATIVE_JOB_IDS_REQUIRED")


def preserve_rows(database: Path) -> dict:
    tables = ("work_requests", "actions", "delivery_attempts", "receipts", "action_reconciliations", "action_dispatch_dispositions",
              "mcp_task_sessions", "mcp_task_writer_leases", "mcp_task_open_idempotency", "mcp_patch_acceptances",
              "mcp_file_read_intents", "mcp_approved_patch_intents", "mcp_standing_patch_intents", "mcp_exec_intents",
              "mcp_artifact_intents", "mcp_document_write_intents", "mcp_read_only_intents")
    return {table: rows(database, "SELECT rowid AS retained_rowid,* FROM " + table + " ORDER BY rowid") for table in tables}


def main() -> None:
    global INSTANCE, EPOCH, NATIVE_PROCESS, NATIVE_SERVER, CONTEXT, PILOT, EXPIRY, PINS
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--pins-b64", required=True)
    parser.add_argument("--mode", required=True, choices=("cold", "warm"))
    parser.add_argument("--root-execute", action="store_true")
    parser.add_argument("--expected-state-sha256")
    args = parser.parse_args()
    PINS = json.loads(base64.b64decode(args.pins_b64, validate=True))
    check_pins(PINS)
    INSTANCE, EPOCH = PINS["service_instance_id"], PINS["activation_epoch_id"]
    NATIVE_PROCESS, NATIVE_SERVER = PINS["process_instance_id"], PINS["server_instance_id"]
    CONTEXT, PILOT, EXPIRY = PINS["context_id"], PINS["pilot_id"], PINS["expires_at_ms"]
    origin, operator, database, health, state, overview, grant = _guard["inspect"]()
    require(health["service_instance_id"] == INSTANCE, "SERVING_INSTANCE_CHANGED")
    authority_guard(overview, grant)
    mcp_origin, authorization = mcp_credentials()
    inventory = call(mcp_origin, authorization, "workspace_context", {"operation": "inventory"})
    targets = [row for row in inventory["targets"] if row.get("binding_id") == _guard["BINDING"]]
    require(len(targets) == 1 and targets[0]["presence_state"] == "online" and targets[0]["readiness"] == "ready"
            and targets[0]["policy_state"] == "enabled", "EXACT_MCP_TARGET_NOT_READY")
    require(inventory["tool_contract"] == PINS["facade_contract"], "REVIEWED_FACADE_CONTRACT_CHANGED")
    task_key, exec_key = mode_keys(args.mode)
    require(not rows(database, "SELECT task_id FROM mcp_task_open_idempotency WHERE principal_id=? AND idempotency_key=?",
                     (_guard["PRINCIPAL"], task_key))
            and not rows(database, "SELECT action_id FROM mcp_exec_intents WHERE principal_id=? AND idempotency_key=?",
                         (_guard["PRINCIPAL"], exec_key)), "MODE_ALREADY_ATTEMPTED_NO_REPLAY")
    cold_key = mode_keys("cold")[1]
    cold = rows(database, "SELECT action_id,task_id FROM mcp_exec_intents WHERE principal_id=? AND idempotency_key=?",
                (_guard["PRINCIPAL"], cold_key))
    if args.mode == "warm":
        require(len(cold) == 1, "SUCCESSFUL_COLD_ATTEMPT_REQUIRED")
        success(terminal_family(database, cold[0]["action_id"], cold[0]["task_id"]))
    else:
        require(not cold, "COLD_ALREADY_ATTEMPTED_NO_REPLAY")
    preflight = {"mode": args.mode, "pins": PINS, "state": state, "grant_sha256": digest(grant),
                 "source_revision": _guard["REVISION"], "package_source_sha256": _guard["PACKAGE"],
                 "binding_id": _guard["BINDING"], "argv": ARGV, "timeout_ms": 300000, "max_output_bytes": 32768}
    emit("r10_mcp_canary_preflight", ok=True, remote_mutation=False, state_sha256=digest(preflight), preflight=preflight,
         timeout_mode_supported=False, native_observation_review_required=True)
    if not args.root_execute:
        return
    require(args.expected_state_sha256 == digest(preflight), "REVIEWED_PREFLIGHT_STATE_REQUIRED")
    retained = preserve_rows(database)
    task = call(mcp_origin, authorization, "workspace_context", {"operation": "task_open", "binding_id": _guard["BINDING"],
                "label": "r10 " + args.mode + " MCP acceptance", "idempotency_key": task_key})
    task_id = task["task"]["task_id"]
    emit("r10_mcp_canary_task_opened", task_id=task_id, mode=args.mode)
    claimed = call(mcp_origin, authorization, "task_control", {"operation": "writer_claim", "task_id": task_id})
    generation = claimed["writer_lease"]["lease_generation"]
    queued = call(mcp_origin, authorization, "exec_command", {"operation": "exec_run", "binding_id": _guard["BINDING"],
                  "task_id": task_id, "argv": ARGV, "cwd": "", "timeout_ms": 300000, "max_output_bytes": 32768,
                  "idempotency_key": exec_key, "expected_facade_contract": PINS["facade_contract"]})
    action_id = queued["action_id"]
    require(queued.get("replayed") is False and queued["task_id"] == task_id, "NEW_ACTION_REQUIRED_NO_REPLAY")
    emit("r10_mcp_canary_queued", mode=args.mode, task_id=task_id, action_id=action_id, replayed=False)
    deadline, renewal, last = time.monotonic() + 540, time.monotonic(), None
    while time.monotonic() < deadline:
        observed = call(mcp_origin, authorization, "exec_command", {"operation": "exec_status", "action_id": action_id})
        key = (observed["execution"], observed["action"]["delivery_state"], observed["action"]["central_lifecycle_state"])
        if key != last:
            emit("r10_mcp_canary_observed", action_id=action_id, execution=key[0], delivery_state=key[1],
                 central_lifecycle_state=key[2], attempts=len(observed["action"]["attempts"]))
            last = key
        require(len(observed["action"]["attempts"]) <= 1, "MULTIPLE_ATTEMPTS_UNSAFE")
        require(key[1] != "reconcile_required", "UNKNOWN_EFFECT_NO_REPLAY_NO_STOP")
        if key[1] == "settled":
            family = terminal_family(database, action_id, task_id)
            try:
                success(family)
                payload = family["payload"]
                output, cursor, total = "", 0, None
                while True:
                    page = call(mcp_origin, authorization, "command_control", {"operation": "exec_output", "action_id": action_id,
                                "cursor": cursor, "max_bytes": 32768})
                    require(page["has_output"] is True and page["exit_code"] == 0 and page["cursor"] == cursor
                            and page["total_bytes"] <= 32768 + 19 and (total is None or total == page["total_bytes"]), "BOUNDED_VERIFIED_OUTPUT_REQUIRED")
                    total = page["total_bytes"]
                    output += page["output"]
                    require(len(output.encode()) <= 65536, "OUTPUT_RECONSTRUCTION_BOUND")
                    if not page["truncated"]:
                        break
                    require(page["next_cursor"] > cursor, "OUTPUT_CURSOR_STALLED")
                    cursor = page["next_cursor"]
                proof = tap_proof(output)
                raw_output = payload["stdout"] + payload["stderr"]
                emit("r10_mcp_canary_terminal", ok=True, mode=args.mode, action_id=action_id, task_id=task_id,
                     attempt_id=family["attempt"]["attempt_id"], command_id=payload["command_id"], job_id=payload["job_id"],
                     runtime_identity=payload["runtime_identity"], response_sha256=payload["response_sha256"],
                     receipt_digest=family["receipt"]["receipt_digest"], exit_code=0, status="exited", timed_out=False,
                     output_bytes=len(raw_output.encode()), output_sha256=hashlib.sha256(raw_output.encode()).hexdigest(),
                     display_output_sha256=hashlib.sha256(output.encode()).hexdigest(), **proof,
                     native_job_correlation_required=True, vm_cleanup_proven=False)
            finally:
                cleanup_family(origin, operator, mcp_origin, authorization, database, action_id, task_id)
                after = preserve_rows(database)
                for table, original in retained.items():
                    require(after[table][:len(original)] == original, "RETAINED_ACTION_TASK_HISTORY_CHANGED")
                final = _guard["state"](database)
                require(final["actions"] == state["actions"] + 1 and final["tasks"] == state["tasks"] + 1
                        and final["acceptances"] == state["acceptances"], "UNEXPECTED_CONCURRENT_ACTION_TASK_CHANGE")
            emit("r10_mcp_canary_complete", ok=True, mode=args.mode, action_id=action_id, task_id=task_id,
                 retained_history_preserved=True, no_retry=True, native_job_correlation_required=True)
            return
        if time.monotonic() - renewal > 25:
            claimed = call(mcp_origin, authorization, "task_control", {"operation": "writer_claim", "task_id": task_id})
            require(claimed["writer_lease"]["lease_generation"] == generation, "WRITER_GENERATION_CHANGED")
            renewal = time.monotonic()
        time.sleep(3)
    raise _guard["GuardFailure"]("OBSERVATION_DEADLINE_NO_REPLAY_NO_STOP")


if __name__ == "__main__":
    try:
        main()
    except Exception as error:
        emit("r10_mcp_canary_refused", ok=False, code=getattr(error, "code", "CANARY_UNEXPECTED_FAILURE"),
             command_replayed=False, vm_cleanup_proven=False, stop_requested=False, root_reconciliation_required=True)
        raise SystemExit(1) from None


